// Each task prompt is the public naming/behavior contract. Checks run in the
// student's namespace AFTER execution; __mupad_output is captured stdout.
// Checks never request input. File exercises use relative paths only.
const lesson = (id, title, explanation, example, prompt, starter, hints, solution, checks, stdin) => ({
  id, title, explanation, example,
  task: { prompt, starter, hints, solution, checks, ...(stdin ? { stdin } : {}) },
});

export const courses = [
  {
    id: 'first-programs', title: 'First programs: make Python speak', level: 'Beginner',
    description: 'Start with visible results, then give values names, calculate useful quantities, reshape text, and turn typed input into data.',
    lessons: [
      lesson('hello-output', 'Your first two lines',
        'A program is a sequence of instructions. Python runs them from top to bottom. The print function sends text to the output panel; quotation marks mark the beginning and end of a string and are not printed. Each print call normally ends its line. Capital letters and spaces inside the quotes matter, so compare your output carefully before changing code.',
        `print("Hello, explorer!")\nprint("One small program, one new skill.")`,
        'Print exactly two lines: first Hello, Python! and then I can write code. Use two print calls. Do not print quotation marks, extra labels, or an extra blank line.',
        `# Print your greeting, then your progress message.\n`,
        ['Put the text you want to display between matching quotation marks.', 'Write print("Hello, Python!") first; the second print call should contain the other required sentence.'],
        `print("Hello, Python!")\nprint("I can write code.")`,
        `assert __mupad_output == "Hello, Python!\\nI can write code.\\n", "Print exactly the two requested lines."`),
      lesson('named-values', 'Names hold values',
        'Assignment binds a name to a value: score = 10 lets later lines refer to score. It is not a mathematical equation or a request to compare two things. Use descriptive lowercase names with underscores. Strings and integers are different kinds of values, even when they look similar on screen. You can give a name a new value later without changing other independent values.',
        `traveler = "Mina"\nsteps = 12\nsteps = steps + 3\nprint(traveler, steps)`,
        'Create name with the string Ada, age with the integer 14, and next_age by adding one to age. Keep age unchanged. Print name and next_age on one line separated by one space.',
        `# Define name, age, and next_age, then print the requested pair.\n`,
        ['Use quotes for the name, but not for the age; adding to a string is not integer arithmetic.', 'Calculate next_age = age + 1, then call print(name, next_age).'],
        `name = "Ada"\nage = 14\nnext_age = age + 1\nprint(name, next_age)`,
        `assert name == "Ada" and isinstance(name, str), "name must be the string Ada."\nassert type(age) is int and age == 14, "age must stay an integer 14."\nassert type(next_age) is int and next_age == age + 1\nassert __mupad_output == "Ada 15\\n"`),
      lesson('packing-arithmetic', 'Divide a job into full groups',
        'Python has several division operators. The / operator returns a division result, // counts complete groups, and % gives the remainder. These are useful when packing objects, converting minutes, or cycling through positions. Parentheses make your calculation order explicit. Keep quantities as numbers until the final display so you can use the result in further calculations.',
        `minutes = 83\nhours = minutes // 60\nremaining = minutes % 60\nprint(hours, remaining)`,
        'A box holds 6 pencils and you have 29 pencils. Define pencils = 29 and box_size = 6. Compute full_boxes and loose_pencils using integer division and remainder, then total_boxes including one partly filled box.',
        `pencils = 29\nbox_size = 6\n# Calculate full_boxes, loose_pencils, and total_boxes.\n`,
        ['Complete boxes do not include the partly filled one; // and % answer different questions.', 'Use pencils // box_size and pencils % box_size. Add one box if the remainder is greater than zero.'],
        `pencils = 29\nbox_size = 6\nfull_boxes = pencils // box_size\nloose_pencils = pencils % box_size\ntotal_boxes = full_boxes + (loose_pencils > 0)`,
        `assert pencils == 29 and box_size == 6\nassert type(full_boxes) is int and full_boxes == 4\nassert type(loose_pencils) is int and loose_pencils == 5\nassert total_boxes == 5\nassert full_boxes * box_size + loose_pencils == pencils`),
      lesson('text-cleanup', 'Clean text and build a label',
        'Strings have methods, which are operations attached to a value. strip removes whitespace at the ends, while title changes the capitalization of words. Neither operation modifies the original string: it returns a new string. An f-string inserts values inside braces. Choosing where you clean a value prevents accidental spaces from becoming part of a displayed label.',
        `raw_city = "  north harbor  "\ncity = raw_city.strip().title()\nlabel = f"Destination: {city}"\nprint(label)`,
        'Keep raw_name = "  ada lovelace  " unchanged. Create clean_name by stripping outer spaces and applying title case. Create greeting with the exact text Welcome, Ada Lovelace! using clean_name, and print greeting.',
        `raw_name = "  ada lovelace  "\n# Create clean_name and greeting.\n`,
        ['Save the result of each string transformation; raw_name does not change by itself.', 'Use raw_name.strip().title() and an f-string shaped like f"Welcome, {clean_name}!".'],
        `raw_name = "  ada lovelace  "\nclean_name = raw_name.strip().title()\ngreeting = f"Welcome, {clean_name}!"\nprint(greeting)`,
        `assert raw_name == "  ada lovelace  ", "Keep the original text."\nassert clean_name == "Ada Lovelace"\nassert greeting == "Welcome, Ada Lovelace!"\nassert __mupad_output == greeting + "\\n"`),
      lesson('typed-input', 'Turn input into a number',
        'input returns a string, even if the user types only digits. Convert that string with int before doing whole-number arithmetic. A prompt is optional; this exercise omits it so the output stays predictable. When a lesson supplies test input, the program receives those lines in order. Reading once and saving the value avoids accidentally asking for the same information twice.',
        `typed_text = "7"\ncount = int(typed_text)\nprint(f"Twice as many: {count * 2}")`,
        'Read one input line without a prompt into minutes_text. Convert it into integer minutes. Set seconds to minutes multiplied by 60, then print exactly 180 seconds for the supplied input 3. Do not hardcode the input value.',
        `minutes_text = input()\n# Convert minutes_text, calculate seconds, and print the label.\n`,
        ['input() gives text; multiplication repeats a string unless you convert it first.', 'Set minutes = int(minutes_text), seconds = minutes * 60, and print an f-string ending in " seconds".'],
        `minutes_text = input()\nminutes = int(minutes_text)\nseconds = minutes * 60\nprint(f"{seconds} seconds")`,
        `assert minutes_text == "3"\nassert type(minutes) is int and minutes == int(minutes_text)\nassert type(seconds) is int and seconds == minutes * 60\nassert __mupad_output == "180 seconds\\n"`, ['3']),
      lesson('boolean-rules', 'Combine true-or-false rules',
        'Comparisons produce Boolean values, True or False. and requires both rules to hold; or accepts either rule; not reverses a Boolean. Parentheses help you group an eligibility rule so its meaning is visible. Boundary values are especially important: at least 12 includes 12, while greater than 12 does not. A Boolean value can be stored like any other result.',
        `age = 12\nheight = 145\ncan_ride = age >= 12 and height >= 140\nprint(can_ride)`,
        'Define age = 12, has_ticket = True, and is_closed = False. Set can_enter to a Boolean that is true only when age is at least 12, a ticket is held, and the venue is not closed. Print can_enter.',
        `age = 12\nhas_ticket = True\nis_closed = False\n# Combine the three conditions into can_enter.\n`,
        ['Use >= for the inclusive age boundary and not to invert the closed flag.', 'The expression is age >= 12 and has_ticket and not is_closed; save its result before printing.'],
        `age = 12\nhas_ticket = True\nis_closed = False\ncan_enter = age >= 12 and has_ticket and not is_closed\nprint(can_enter)`,
        `assert age == 12 and has_ticket is True and is_closed is False\nassert can_enter is True, "The boundary age is allowed."\nassert __mupad_output == "True\\n"`),
    ],
  },
  {
    id: 'decisions-and-data', title: 'Decisions, loops, and everyday data', level: 'Beginner',
    description: 'Give programs choices and repetition, then organize related values in lists and dictionaries. Learn to handle empty collections from the start.',
    lessons: [
      lesson('temperature-branches', 'Choose one branch',
        'An if statement selects a block according to a condition. elif adds another test only when earlier tests failed, and else catches everything left. Indentation defines the blocks. Wrap this decision in a small function so you can try several values without copying the decision. return sends the answer to the caller; printing is a separate choice made by that caller.',
        `def weather_label(degrees):\n    if degrees < 0:\n        return "freezing"\n    elif degrees < 20:\n        return "cool"\n    else:\n        return "warm"\n\nprint(weather_label(20))`,
        'Define temperature_label(degrees). Return "cold" below 10, "mild" from 10 up to but not including 25, and "hot" at 25 or above. Return strings rather than printing them. Support negative and fractional temperatures.',
        `def temperature_label(degrees):\n    # Choose the correct category.\n    pass\n`,
        ['Test the lowest interval first; later branches only receive values not already handled.', 'Use if degrees < 10, elif degrees < 25, and an else branch, each with a return statement.'],
        `def temperature_label(degrees):\n    if degrees < 10:\n        return "cold"\n    elif degrees < 25:\n        return "mild"\n    return "hot"`,
        `assert temperature_label(-8) == "cold"\nassert temperature_label(9.9) == "cold"\nassert temperature_label(10) == "mild"\nassert temperature_label(24.9) == "mild"\nassert temperature_label(25) == "hot"\nassert temperature_label(100) == "hot"`),
      lesson('range-total', 'Build a running total',
        'A for loop visits the values in an iterable. range gives an efficient sequence of integers; its stop value is excluded. An accumulator starts at an identity value, usually zero for addition, and is updated for every item. Initialize it before the loop so an empty iteration still has a valid answer. Return after the loop, not inside it, or only the first item will be counted.',
        `total = 0\nfor number in range(1, 5):\n    total += number\nprint(total)`,
        'Define sum_to(n) for nonnegative integer n. Return the sum of the integers 1 through n, including n, by accumulating in a for loop. sum_to(0) must return 0. Do not print the result inside the function.',
        `def sum_to(n):\n    total = 0\n    # Add each integer from 1 through n.\n    return total\n`,
        ['range excludes its stop, so the last requested integer requires a stop one larger.', 'Loop over range(1, n + 1), add each number to total, and keep return outside the loop.'],
        `def sum_to(n):\n    total = 0\n    for number in range(1, n + 1):\n        total += number\n    return total`,
        `assert sum_to(0) == 0\nassert sum_to(1) == 1\nassert sum_to(5) == 15\nassert sum_to(20) == 210\nassert sum_to(100) == 5050`),
      lesson('while-digits', 'Repeat until nothing remains',
        'A while loop repeats while its condition is true. Unlike a for loop, you must ensure the body moves toward stopping. Integer division can discard the last decimal digit, and remainder can retrieve that digit. A loop with a condition that is false at the start runs zero times. Design that case deliberately, especially for zero and empty values.',
        `remaining = 407\ntotal = 0\nwhile remaining > 0:\n    total += remaining % 10\n    remaining //= 10\nprint(total)`,
        'Define digit_sum(number) for any integer. Return the sum of its decimal digits, ignoring a negative sign. Use abs to normalize the sign and a while loop to remove digits. Return 0 for number = 0.',
        `def digit_sum(number):\n    remaining = abs(number)\n    total = 0\n    # Consume one digit per iteration.\n    return total\n`,
        ['The last digit is remaining % 10. Remove it using integer division by 10.', 'While remaining > 0, add the last digit to total and set remaining //= 10.'],
        `def digit_sum(number):\n    remaining = abs(number)\n    total = 0\n    while remaining > 0:\n        total += remaining % 10\n        remaining //= 10\n    return total`,
        `assert digit_sum(0) == 0\nassert digit_sum(407) == 11\nassert digit_sum(-9302) == 14\nassert digit_sum(100000) == 1\nassert digit_sum(99999) == 45`),
      lesson('list-filter', 'Keep selected list items',
        'A list keeps an ordered collection of values. You can build a new list with append while visiting an existing list. Filtering decides which items to keep, without needing to remove items during iteration. Preserving order and duplicates is often important: two matching measurements are still two measurements. A fresh result list also avoids surprising changes to the caller’s data.',
        `readings = [3, -1, 0, 8]\nkept = []\nfor reading in readings:\n    if reading >= 0:\n        kept.append(reading)\nprint(kept)`,
        'Define nonnegative(values). Return a new list containing every value greater than or equal to zero, in its original order. Preserve duplicates and do not modify values. An empty input must produce an empty list.',
        `def nonnegative(values):\n    result = []\n    # Append qualifying values to result.\n    return result\n`,
        ['Zero belongs in the result. Iterate over the input rather than deleting from it.', 'For each value, test value >= 0 and call result.append(value) only when that test succeeds.'],
        `def nonnegative(values):\n    result = []\n    for value in values:\n        if value >= 0:\n            result.append(value)\n    return result`,
        `assert nonnegative([]) == []\nassert nonnegative([-3, -1]) == []\n_data = [-2, 0, 5, 0, -1, 2.5]\nassert nonnegative(_data) == [0, 5, 0, 2.5]\nassert _data == [-2, 0, 5, 0, -1, 2.5], "Do not mutate the input."\nassert nonnegative(_data) is not _data`),
      lesson('dictionary-stock', 'Look up values by name',
        'A dictionary maps keys to values: a product name can point to its quantity. Square-bracket lookup raises an error for a missing key, while get lets you supply a fallback. Copying a dictionary creates a separate container before updating it. Decide whether an operation mutates its input or returns a new mapping, and make that choice part of the function’s contract.',
        `stock = {"tea": 4}\nupdated = stock.copy()\nupdated["tea"] = updated.get("tea", 0) + 2\nupdated["coffee"] = updated.get("coffee", 0) + 1\nprint(stock, updated)`,
        'Define restock(stock, item, amount). Return a new dictionary whose quantity for item is increased by the nonnegative integer amount. Treat a missing item as zero. Preserve every other item and leave stock unchanged.',
        `def restock(stock, item, amount):\n    # Copy the mapping, then update one quantity.\n    pass\n`,
        ['A direct assignment to stock[item] changes the caller’s dictionary; copy it first.', 'Use updated = stock.copy(), then updated[item] = updated.get(item, 0) + amount, and return updated.'],
        `def restock(stock, item, amount):\n    updated = stock.copy()\n    updated[item] = updated.get(item, 0) + amount\n    return updated`,
        `_stock = {"tea": 4, "rice": 1}\nassert restock(_stock, "tea", 3) == {"tea": 7, "rice": 1}\nassert restock(_stock, "beans", 2) == {"tea": 4, "rice": 1, "beans": 2}\nassert restock({}, "tea", 0) == {"tea": 0}\nassert _stock == {"tea": 4, "rice": 1}\nassert restock(_stock, "tea", 0) is not _stock`),
      lesson('comprehension-labels', 'Transform and filter in one expression',
        'A list comprehension describes the values of a new list in a compact expression. Read it as: compute this expression for each item, optionally keeping only items that satisfy a condition. Prefer clear comprehensions to dense nested ones. If a transformation is used twice, a regular loop can avoid repeating work. In this lesson whitespace-only strings count as empty after cleaning.',
        `words = ["  sun ", "", " moon"]\nlabels = [word.strip().upper() for word in words if word.strip()]\nprint(labels)`,
        'Define clean_labels(words). Return stripped, uppercase versions of the nonblank strings in words. Drop strings whose stripped value is empty, but preserve original order and duplicates. Keep the original list unchanged.',
        `def clean_labels(words):\n    # Build the cleaned list, skipping blank entries.\n    pass\n`,
        ['Check the stripped word, not the original word: a string of spaces is not initially empty.', 'Use [word.strip().upper() for word in words if word.strip()] as the returned expression.'],
        `def clean_labels(words):\n    return [word.strip().upper() for word in words if word.strip()]`,
        `assert clean_labels([]) == []\nassert clean_labels(["", "  ", "\\t"]) == []\n_words = [" sun ", "", "Moon", "sun", " café "]\nassert clean_labels(_words) == ["SUN", "MOON", "SUN", "CAFÉ"]\nassert _words == [" sun ", "", "Moon", "sun", " café "]`),
    ],
  },
  {
    id: 'reusable-functions', title: 'Functions that are easy to reuse', level: 'Intermediate',
    description: 'Build precise function contracts, handle optional arguments safely, summarize collections, and solve a small problem recursively.',
    lessons: [
      lesson('function-clamp', 'Specify a function contract',
        'A function packages a calculation behind a name and parameters. A useful contract explains accepted inputs and the returned value. Keeping printing outside the function makes it reusable in an editor, a test, or a larger program. Clamping restricts a value to an interval: values below the lower bound become the lower bound, while values already inside remain unchanged.',
        `def cap_at(value, maximum):\n    return min(value, maximum)\n\nprint(cap_at(17, 10))`,
        'Define clamp(value, low, high), assuming low <= high. Return low when value is below low, high when it is above high, otherwise value itself. Support integers and floats, including an interval where low equals high.',
        `def clamp(value, low, high):\n    # Return the value restricted to the inclusive interval.\n    pass\n`,
        ['Handle the two out-of-range directions separately; equality belongs inside the interval.', 'Either use two comparisons or return max(low, min(value, high)).'],
        `def clamp(value, low, high):\n    return max(low, min(value, high))`,
        `assert clamp(-5, 0, 10) == 0\nassert clamp(15, 0, 10) == 10\nassert clamp(4, 0, 10) == 4\nassert clamp(0, 0, 10) == 0\nassert clamp(10, 0, 10) == 10\nassert clamp(2.5, -1.5, 3.5) == 2.5\nassert clamp(20, 7, 7) == 7`),
      lesson('safe-defaults', 'Use optional arguments without shared state',
        'Default argument values are created when a function is defined, not each time it is called. A mutable default such as [] can therefore retain changes across calls. None is a useful marker meaning no list was supplied. Returning a copy instead of modifying a supplied list gives callers control of their own data and makes repeated calls predictable.',
        `def with_tag(tag, tags=None):\n    result = [] if tags is None else list(tags)\n    result.append(tag)\n    return result\n\nprint(with_tag("new"))\nprint(with_tag("other"))`,
        'Define add_guest(name, guests=None). Return a new list containing the supplied guests followed by name. When guests is omitted, start with an empty list. Never change a supplied list or share state between separate calls.',
        `def add_guest(name, guests=None):\n    # Make a fresh list on every call.\n    pass\n`,
        ['Use None as the default marker, then create a new list inside the function.', 'Copy guests with list(guests) when it is provided, otherwise use []; append name to that new list.'],
        `def add_guest(name, guests=None):\n    result = [] if guests is None else list(guests)\n    result.append(name)\n    return result`,
        `assert add_guest("Ada") == ["Ada"]\nassert add_guest("Bo") == ["Bo"], "Calls must not share a default list."\n_guests = ["Mina"]\nassert add_guest("Ada", _guests) == ["Mina", "Ada"]\nassert _guests == ["Mina"]\nassert add_guest("Ada", []) == ["Ada"]\nassert add_guest("Mina", _guests) == ["Mina", "Mina"]`),
      lesson('word-frequency', 'Count with a dictionary',
        'Counting is a common dictionary pattern. For each item, read its existing count with get and add one. Normalizing before counting groups different spellings of the same token. split without an argument handles runs of whitespace, including tabs and newlines. It does not remove punctuation, so be explicit about whether a token such as hello! should match hello.',
        `counts = {}\nfor word in "Red blue red".lower().split():\n    counts[word] = counts.get(word, 0) + 1\nprint(counts)`,
        'Define word_counts(text). Split on whitespace, lowercase each token, and return a dictionary of token frequencies. Do not strip punctuation: "hi" and "hi!" are distinct keys. Empty or whitespace-only text returns {}.',
        `def word_counts(text):\n    counts = {}\n    # Normalize and count each whitespace-separated token.\n    return counts\n`,
        ['Call lower and split on text, then use a zero fallback for the first occurrence of a word.', 'In a loop over text.lower().split(), assign counts[word] = counts.get(word, 0) + 1.'],
        `def word_counts(text):\n    counts = {}\n    for word in text.lower().split():\n        counts[word] = counts.get(word, 0) + 1\n    return counts`,
        `assert word_counts("") == {}\nassert word_counts(" \\t\\n ") == {}\nassert word_counts("Red blue RED") == {"red": 2, "blue": 1}\nassert word_counts("hi hi! HI") == {"hi": 2, "hi!": 1}\nassert word_counts("Café\\nCAFÉ") == {"café": 2}`),
      lesson('tuple-summary', 'Return more than one answer',
        'A tuple groups a fixed set of values. A function can return a pair, and the caller can unpack it into two names. Distinguish an empty result from an actual numerical zero: None can represent the absence of measurements. When calculating an average, divide by the number of values only after establishing that the collection is not empty.',
        `def bounds(values):\n    if not values:\n        return (None, None)\n    return (min(values), max(values))\n\nlowest, highest = bounds([4, 9, 2])\nprint(lowest, highest)`,
        'Define summarize(values) for a list of numbers. Return a tuple (total, average). For an empty list return (0, None); otherwise average is total divided by length. Do not mutate values, and preserve fractional averages.',
        `def summarize(values):\n    # Decide the empty case before dividing.\n    pass\n`,
        ['sum([]) is zero, but division by len([]) is invalid; use None for its absent average.', 'Compute total = sum(values), then return (total, total / len(values)) only when values is nonempty.'],
        `def summarize(values):\n    total = sum(values)\n    if not values:\n        return (0, None)\n    return (total, total / len(values))`,
        `assert summarize([]) == (0, None)\nassert isinstance(summarize([1]), tuple)\nassert summarize([1, 2]) == (3, 1.5)\nassert summarize([-4, 4]) == (0, 0.0)\n_values = [2.5, 3.5]\nassert summarize(_values) == (6.0, 3.0)\nassert _values == [2.5, 3.5]`),
      lesson('sort-key', 'Sort by a custom rule',
        'sorted returns a new list rather than changing the original. Its key argument supplies a function that computes a comparison value for each item. A tuple key gives a primary rule and a tie-breaker: Python compares the first fields, then the next fields if needed. Define all your ordering rules so the result is deterministic even when many items have equal length.',
        `names = ["Zoe", "Al", "Bea"]\nordered = sorted(names, key=lambda name: (len(name), name.lower(), name))\nprint(ordered)\nprint(names)`,
        'Define order_names(names). Return a new list sorted first by length, then by lowercase spelling, then by original spelling to break case-only ties. Preserve duplicate names and leave the input unchanged. An empty list stays empty.',
        `def order_names(names):\n    # Supply a tuple-valued sorting key.\n    pass\n`,
        ['Use sorted instead of list.sort so the caller’s list stays intact.', 'Return sorted(names, key=lambda name: (len(name), name.lower(), name)).'],
        `def order_names(names):\n    return sorted(names, key=lambda name: (len(name), name.lower(), name))`,
        `assert order_names([]) == []\n_names = ["zoe", "Al", "Bea", "al", "AL", "Bea"]\nassert order_names(_names) == ["AL", "Al", "al", "Bea", "Bea", "zoe"]\nassert _names == ["zoe", "Al", "Bea", "al", "AL", "Bea"]\nassert order_names(["x"]) is not _names\nassert order_names(["bb", "a", "AA"]) == ["a", "AA", "bb"]`),
      lesson('recursive-flatten', 'Break a nested problem into smaller ones',
        'Recursion means a function calls itself on a smaller problem. It needs a base case that does not recurse forever. For nested lists, each element is either another list to explore or a value to keep. extend adds all elements from a returned list, while append adds a single element. This technique handles irregular nesting without choosing a fixed number of nested loops.',
        `def count_leaves(items):\n    total = 0\n    for item in items:\n        total += count_leaves(item) if isinstance(item, list) else 1\n    return total\n\nprint(count_leaves([1, [2, [], [3]]]))`,
        'Define flatten(items) for a list whose elements may be nested lists or arbitrary non-list values. Return the leaf values in left-to-right order in a new flat list. Recurse only into lists; strings and tuples remain whole values. Do not mutate input.',
        `def flatten(items):\n    result = []\n    # Recurse into lists; append every other value intact.\n    return result\n`,
        ['An empty list naturally contributes no values. Check isinstance(item, list) before recurring.', 'For a nested list use result.extend(flatten(item)); otherwise use result.append(item).'],
        `def flatten(items):\n    result = []\n    for item in items:\n        if isinstance(item, list):\n            result.extend(flatten(item))\n        else:\n            result.append(item)\n    return result`,
        `assert flatten([]) == []\nassert flatten([[], [[], []]]) == []\n_items = [1, [2, [], [3]], "ab", (4, 5), None]\nassert flatten(_items) == [1, 2, 3, "ab", (4, 5), None]\nassert _items == [1, [2, [], [3]], "ab", (4, 5), None]\nassert flatten([[[0]], False]) == [0, False]`),
    ],
  },
  {
    id: 'reliable-programs', title: 'Errors, files, and structured records', level: 'Intermediate',
    description: 'Treat invalid data deliberately, use narrow exception handling, and read or write text, JSON, and CSV using Python’s standard library.',
    lessons: [
      lesson('parse-integer', 'Recover from an expected error',
        'An exception signals that an operation could not complete. A try block marks the risky operation, and except selects the failures you know how to handle. Catching every exception can hide programming mistakes. int raises ValueError for invalid numeric text; handle that specific error here. A default result makes an unsuccessful parse explicit without crashing the whole program.',
        `def parse_count(text):\n    try:\n        return int(text)\n    except ValueError:\n        return None\n\nprint(parse_count(" 12 "))\nprint(parse_count("many"))`,
        'Define parse_integer(text, default=None), accepting string text. Return int(text) when conversion succeeds, or default on ValueError. Do not accept decimal text such as "2.5" by truncating it. Preserve the exact supplied default object.',
        `def parse_integer(text, default=None):\n    # Try integer conversion and handle invalid text only.\n    pass\n`,
        ['Put int(text) in a try block; only ValueError should trigger the fallback.', 'Return int(text) in try, then return default in except ValueError.'],
        `def parse_integer(text, default=None):\n    try:\n        return int(text)\n    except ValueError:\n        return default`,
        `assert parse_integer("  +12 ") == 12\nassert parse_integer("-7") == -7\nassert parse_integer("0") == 0\nassert parse_integer("2.5") is None\nassert parse_integer("") is None\n_marker = object()\nassert parse_integer("no", _marker) is _marker\nassert parse_integer("9", _marker) == 9`),
      lesson('validate-score', 'Raise a useful error',
        'Some inputs can be converted successfully but still violate your program’s rules. Raising ValueError distinguishes an invalid value from a valid result. Check the contract at the boundary of a function, before doing its main work. Clear messages help callers understand the rejected input. Returning a magic value such as -1 would be ambiguous when negative results are otherwise possible.',
        `def percentage(part, whole):\n    if whole <= 0:\n        raise ValueError("whole must be positive")\n    return 100 * part / whole\n\nprint(percentage(3, 4))`,
        'Define normalized_score(score, maximum). Accept numeric inputs. Raise ValueError if maximum <= 0 or score is outside the inclusive range 0..maximum. Otherwise return score / maximum, not a percentage. Include a nonempty error message.',
        `def normalized_score(score, maximum):\n    # Validate the range before dividing.\n    pass\n`,
        ['A zero maximum cannot be divided by; a score below zero or above maximum is also invalid.', 'Raise ValueError with a message when maximum <= 0 or not 0 <= score <= maximum, then return score / maximum.'],
        `def normalized_score(score, maximum):\n    if maximum <= 0 or not 0 <= score <= maximum:\n        raise ValueError("maximum must be positive and score must be in range")\n    return score / maximum`,
        `assert normalized_score(0, 10) == 0\nassert normalized_score(10, 10) == 1\nassert normalized_score(2.5, 5) == 0.5\nfor _score, _maximum in [(1, 0), (0, -1), (-1, 10), (11, 10)]:\n    try:\n        normalized_score(_score, _maximum)\n    except ValueError as _error:\n        assert str(_error), "Explain why the value is invalid."\n    else:\n        raise AssertionError("Invalid scores must raise ValueError.")`),
      lesson('text-file-save', 'Write text with a context manager',
        'open creates a file object, and with closes it even if an error happens inside the block. Write mode replaces existing content rather than appending. Explicit UTF-8 encoding keeps non-ASCII text portable. A newline is a character in the text: adding one after each item creates a conventional line-based file, including a trailing newline after the last item.',
        `with open("notes.txt", "w", encoding="utf-8") as handle:\n    handle.write("Remember the map\\n")\nwith open("notes.txt", encoding="utf-8") as handle:\n    print(handle.read())`,
        'Define save_lines(path, lines). Overwrite the text file at path using UTF-8, writing every supplied string followed by one newline. Assume strings have no embedded newlines. Return the number of strings written. Empty input must create an empty file.',
        `def save_lines(path, lines):\n    # Open in write mode, write each line, return the count.\n    pass\n`,
        ['Use a with block and mode "w"; append "\\n" to each line before writing.', 'Track a count inside the loop or return len(lines) after writing the whole list.'],
        `def save_lines(path, lines):\n    count = 0\n    with open(path, "w", encoding="utf-8") as handle:\n        for line in lines:\n            handle.write(line + "\\n")\n            count += 1\n    return count`,
        `from pathlib import Path as _Path\n_path = _Path("mupad-lines-check.txt")\nassert save_lines(_path, ["café", "", "moon"]) == 3\nassert _path.read_text(encoding="utf-8") == "café\\n\\nmoon\\n"\nassert save_lines(_path, ["replacement"]) == 1\nassert _path.read_text(encoding="utf-8") == "replacement\\n"\nassert save_lines(_path, []) == 0\nassert _path.read_text(encoding="utf-8") == ""`),
      lesson('text-file-read', 'Read meaningful lines',
        'A text file can be iterated one line at a time, which avoids loading the whole file at once. Each line may carry a newline and surrounding spaces; strip cleans them before applying your rule. A simple configuration format can ignore blank lines and comments. Keep reading errors visible rather than pretending a missing file is an empty configuration.',
        `with open("settings.txt", "w", encoding="utf-8") as handle:\n    handle.write("# route\\n harbor \\n\\n")\nwith open("settings.txt", encoding="utf-8") as handle:\n    entries = [line.strip() for line in handle if line.strip() and not line.strip().startswith("#")]\nprint(entries)`,
        'Define read_entries(path). Read UTF-8 text and return stripped nonempty lines, skipping any line whose stripped version starts with #. Preserve order, duplicates, and inline # characters. Let FileNotFoundError propagate for a missing file.',
        `def read_entries(path):\n    # Strip each line before checking blanks and comments.\n    pass\n`,
        ['A comment starts with # after stripping; an inline # is ordinary content.', 'Use a with open block, strip each line, and append it when it is nonempty and not startswith("#").'],
        `def read_entries(path):\n    result = []\n    with open(path, encoding="utf-8") as handle:\n        for line in handle:\n            entry = line.strip()\n            if entry and not entry.startswith("#"):\n                result.append(entry)\n    return result`,
        `from pathlib import Path as _Path\n_path = _Path("mupad-entries-check.txt")\n_path.write_text("  # comment\\n\\n café \\nitem # note\\ncafé\\n \\t\\n", encoding="utf-8")\nassert read_entries(_path) == ["café", "item # note", "café"]\n_path.write_text("", encoding="utf-8")\nassert read_entries(_path) == []\ntry:\n    read_entries("mupad-definitely-missing.txt")\nexcept FileNotFoundError:\n    pass\nelse:\n    raise AssertionError("A missing file must not be treated as empty.")`),
      lesson('json-settings', 'Decode and validate JSON',
        'JSON represents structured values as text. json.loads parses that text into Python dictionaries, lists, numbers, and other values. Parsing alone does not guarantee the shape your program expects. Validate required fields separately and remember that bool is a subclass of int in Python; an exact type check distinguishes a true port number from True. Extra settings can remain untouched.',
        `import json\nsettings = json.loads('{"host": "localhost", "port": 8080}')\nprint(settings["host"], settings["port"])`,
        'Define load_settings(text). Decode JSON and require a dictionary with a nonblank string host and an integer port from 1 to 65535 (reject booleans). Return the decoded dictionary unchanged, including extra keys. Raise ValueError for malformed JSON or invalid shape.',
        `import json\n\ndef load_settings(text):\n    # Parse, validate host and port, then return the mapping.\n    pass\n`,
        ['Validate the dictionary before calling get. json.loads already raises a ValueError subclass for malformed JSON.', 'Require isinstance(host, str) and host.strip(), then type(port) is int and 1 <= port <= 65535.'],
        `import json\n\ndef load_settings(text):\n    data = json.loads(text)\n    if not isinstance(data, dict):\n        raise ValueError("settings must be an object")\n    host = data.get("host")\n    port = data.get("port")\n    if not isinstance(host, str) or not host.strip():\n        raise ValueError("host must be nonblank text")\n    if type(port) is not int or not 1 <= port <= 65535:\n        raise ValueError("port must be an integer from 1 to 65535")\n    return data`,
        `assert load_settings('{"host":" café ","port":1,"debug":true}') == {"host": " café ", "port": 1, "debug": True}\nassert load_settings('{"host":"local","port":65535}')["port"] == 65535\nfor _text in ['{', '[]', 'null', '{}', '{"host":" ","port":80}', '{"host":8,"port":80}', '{"host":"x","port":true}', '{"host":"x","port":0}', '{"host":"x","port":65536}', '{"host":"x","port":80.0}']:\n    try:\n        load_settings(_text)\n    except ValueError:\n        pass\n    else:\n        raise AssertionError("Reject malformed or invalid settings: " + _text)`),
      lesson('csv-totals', 'Read quoted tabular data',
        'CSV is not safely parsed by splitting every line at commas: quoted cells may contain commas or even line breaks. csv.DictReader handles those details and maps each cell to its header name. io.StringIO makes a string act like a readable file, which is convenient for testing. Convert numeric cells explicitly before adding them to a running total.',
        `import csv\nimport io\ntext = 'item,quantity\\n"tea, green",2\\nrice,3\\n'\nfor row in csv.DictReader(io.StringIO(text)):\n    print(row["item"], int(row["quantity"]))`,
        'Define inventory_totals(csv_text). Parse CSV text with headers item,quantity. Return a dictionary summing integer quantities for repeated item names. Preserve item names exactly, including quoted commas. Valid quantities may be negative; header-only input returns {}.',
        `import csv\nimport io\n\ndef inventory_totals(csv_text):\n    totals = {}\n    # Use DictReader and add each row's quantity.\n    return totals\n`,
        ['Use csv.DictReader(io.StringIO(csv_text)) instead of splitting at commas yourself.', 'Read row["item"], convert row["quantity"] with int, and add it to totals.get(item, 0).'],
        `import csv\nimport io\n\ndef inventory_totals(csv_text):\n    totals = {}\n    for row in csv.DictReader(io.StringIO(csv_text)):\n        item = row["item"]\n        totals[item] = totals.get(item, 0) + int(row["quantity"])\n    return totals`,
        `assert inventory_totals("item,quantity\\n") == {}\nassert inventory_totals('item,quantity\\n"tea, green",2\\nrice,3\\n"tea, green",-1\\n') == {"tea, green": 1, "rice": 3}\nassert inventory_totals('item,quantity\\r\\n"café",0\\r\\ncafé,4\\r\\n') == {"café": 4}\nassert inventory_totals('item,quantity\\n"two\\nlines",5\\n') == {"two\\nlines": 5}`),
    ],
  },
  {
    id: 'objects-and-protocols', title: 'Objects, state, and Python protocols', level: 'Advanced',
    description: 'Model small domains with classes, enforce invariants, reuse behavior with inheritance, and design objects that participate in iteration.',
    lessons: [
      lesson('class-counter', 'Give each object its own state',
        'A class describes a family of objects. __init__ initializes each new instance, and self refers to that specific instance inside its methods. Instance attributes keep independent objects independent. Storing mutable or changing state as a class attribute can accidentally share it. Methods can update state and return the new value, making the effect easy for callers to observe.',
        `class Score:\n    def __init__(self, points=0):\n        self.points = points\n\n    def gain(self, amount):\n        self.points += amount\n        return self.points\n\nscore = Score(4)\nprint(score.gain(3))`,
        'Define Counter(start=0) with instance attribute value. Its increment(step=1) method adds step to value and returns the new value. Steps may be positive, zero, or negative. New counters must not share state.',
        `class Counter:\n    def __init__(self, start=0):\n        # Store independent instance state.\n        pass\n\n    def increment(self, step=1):\n        pass\n`,
        ['Assign self.value inside __init__, and read or update it through self in increment.', 'Set self.value = start; increment uses self.value += step followed by return self.value.'],
        `class Counter:\n    def __init__(self, start=0):\n        self.value = start\n\n    def increment(self, step=1):\n        self.value += step\n        return self.value`,
        `_first, _second = Counter(), Counter(10)\nassert _first.value == 0 and _second.value == 10\nassert _first.increment() == 1\nassert _first.increment(4) == 5\nassert _first.increment(-2) == 3\nassert _first.increment(0) == 3\nassert _second.value == 10\nassert _second.increment() == 11\nassert _first.value == 3`),
      lesson('account-invariants', 'Protect a state invariant',
        'An invariant is a rule that must stay true for the lifetime of an object. A bank account here never has a negative balance. Validate a proposed operation before changing state so failed operations leave the account intact. The constructor must follow the same rule as later methods. Exceptions communicate invalid requests; successful methods can return the updated balance.',
        `class Meter:\n    def __init__(self, value=0):\n        if value < 0:\n            raise ValueError("value must be nonnegative")\n        self.value = value\n\n    def add(self, amount):\n        if amount < 0:\n            raise ValueError("amount must be nonnegative")\n        self.value += amount\n        return self.value\n\nprint(Meter(2).add(3))`,
        'Define Account(balance=0) with balance, deposit(amount), and withdraw(amount). Reject negative initial balances, negative amounts, and withdrawals exceeding balance with ValueError. Successful methods return the new balance. Failed operations must leave balance unchanged; zero is allowed.',
        `class Account:\n    def __init__(self, balance=0):\n        pass\n\n    def deposit(self, amount):\n        pass\n\n    def withdraw(self, amount):\n        pass\n`,
        ['Check amounts before changing self.balance; a rejected withdrawal must not partially change state.', 'Validate balance in __init__, amount < 0 in both methods, and amount > self.balance in withdraw.'],
        `class Account:\n    def __init__(self, balance=0):\n        if balance < 0:\n            raise ValueError("balance must be nonnegative")\n        self.balance = balance\n\n    def deposit(self, amount):\n        if amount < 0:\n            raise ValueError("deposit must be nonnegative")\n        self.balance += amount\n        return self.balance\n\n    def withdraw(self, amount):\n        if amount < 0 or amount > self.balance:\n            raise ValueError("invalid withdrawal")\n        self.balance -= amount\n        return self.balance`,
        `_account = Account(10)\nassert _account.deposit(2.5) == 12.5\nassert _account.withdraw(2.5) == 10\nassert _account.deposit(0) == 10\nassert _account.withdraw(0) == 10\nfor _operation in [lambda: _account.deposit(-1), lambda: _account.withdraw(-1), lambda: _account.withdraw(11)]:\n    try:\n        _operation()\n    except ValueError:\n        assert _account.balance == 10\n    else:\n        raise AssertionError("Reject the invalid operation.")\nassert _account.withdraw(10) == 0\nassert Account().balance == 0\ntry:\n    Account(-1)\nexcept ValueError:\n    pass\nelse:\n    raise AssertionError("Reject a negative opening balance.")`),
      lesson('computed-property', 'Expose a computed property',
        'A property lets callers read a computed value with attribute syntax. It can express a value that depends on other attributes without storing a duplicate that might become stale. A read-only property has a getter but no setter. When the underlying dimensions change, the next access calculates the current result. Choose properties for inexpensive, unsurprising calculations.',
        `class Square:\n    def __init__(self, side):\n        self.side = side\n\n    @property\n    def area(self):\n        return self.side ** 2\n\nshape = Square(3)\nshape.side = 4\nprint(shape.area)`,
        'Define Rectangle(width, height) with public width and height attributes and read-only properties area and perimeter. Assume nonnegative dimensions. Properties must reflect later dimension changes: area is width * height and perimeter is 2 * (width + height).',
        `class Rectangle:\n    def __init__(self, width, height):\n        self.width = width\n        self.height = height\n\n    # Add read-only area and perimeter properties.\n`,
        ['Use @property above a method so callers write rectangle.area rather than rectangle.area().', 'Each getter computes from self.width and self.height; do not assign a cached area in __init__.'],
        `class Rectangle:\n    def __init__(self, width, height):\n        self.width = width\n        self.height = height\n\n    @property\n    def area(self):\n        return self.width * self.height\n\n    @property\n    def perimeter(self):\n        return 2 * (self.width + self.height)`,
        `_rectangle = Rectangle(3, 4)\nassert _rectangle.area == 12 and _rectangle.perimeter == 14\n_rectangle.width = 5\nassert _rectangle.area == 20 and _rectangle.perimeter == 18\nassert Rectangle(0, 2).area == 0\nassert Rectangle(1.5, 2).perimeter == 7\nassert isinstance(Rectangle.area, property) and isinstance(Rectangle.perimeter, property)\ntry:\n    _rectangle.area = 100\nexcept AttributeError:\n    pass\nelse:\n    raise AssertionError("area must be read-only.")`),
      lesson('inheritance-ticket', 'Specialize an existing class',
        'Inheritance gives a subclass the behavior of a parent class and lets it replace selected methods. super calls a parent implementation without hardcoding its name. Reuse the parent’s initialization instead of duplicating state rules. A subclass should still work wherever the parent’s interface is expected: callers should not need to know which concrete class they were given.',
        `class Greeting:\n    def __init__(self, name):\n        self.name = name\n\n    def message(self):\n        return f"Hello, {self.name}"\n\nclass ExcitedGreeting(Greeting):\n    def message(self):\n        return super().message() + "!"\n\nprint(ExcitedGreeting("Ada").message())`,
        'Define Ticket(price) storing price and a cost() method returning it. Define DiscountTicket(price, discount) inheriting from Ticket, where discount is a fraction from 0 to 1. Its cost() returns the base cost times (1 - discount). Leave price unchanged.',
        `class Ticket:\n    def __init__(self, price):\n        pass\n\n    def cost(self):\n        pass\n\nclass DiscountTicket(Ticket):\n    # Initialize both fields and specialize cost().\n    pass\n`,
        ['Call super().__init__(price) to initialize the inherited price field.', 'Store self.discount and return super().cost() * (1 - self.discount) in the subclass cost method.'],
        `class Ticket:\n    def __init__(self, price):\n        self.price = price\n\n    def cost(self):\n        return self.price\n\nclass DiscountTicket(Ticket):\n    def __init__(self, price, discount):\n        super().__init__(price)\n        self.discount = discount\n\n    def cost(self):\n        return super().cost() * (1 - self.discount)`,
        `assert Ticket(20).cost() == 20\nassert issubclass(DiscountTicket, Ticket)\n_ticket = DiscountTicket(20, 0.25)\nassert _ticket.cost() == 15 and _ticket.price == 20\nassert _ticket.discount == 0.25\nassert DiscountTicket(20, 0).cost() == 20\nassert DiscountTicket(20, 1).cost() == 0\nassert DiscountTicket(0, 0.5).cost() == 0\n_ticket.price = 40\nassert _ticket.cost() == 30`),
      lesson('dataclass-point', 'Use a dataclass for value objects',
        'A dataclass generates useful methods for a class whose main job is storing fields. Type annotations name the fields; they do not automatically validate their values. frozen=True prevents normal reassignment and makes suitable value objects hashable. Keep operations such as distance as explicit methods. Two points with the same coordinates then compare equal, independent of object identity.',
        `from dataclasses import dataclass\n\n@dataclass(frozen=True)\nclass Color:\n    red: int\n    green: int\n    blue: int\n\nprint(Color(1, 2, 3) == Color(1, 2, 3))`,
        'Define a frozen dataclass Point with numeric fields x and y and a distance_to(other) method returning Euclidean distance. Coordinates may be negative or fractional. Equality must compare coordinates, and assigning a new x or y after creation must fail.',
        `from dataclasses import dataclass\nimport math\n\n# Define frozen Point and its distance_to method.\n`,
        ['Use @dataclass(frozen=True) and field annotations x: float and y: float.', 'math.hypot(self.x - other.x, self.y - other.y) computes the distance without a manual square-root expression.'],
        `from dataclasses import dataclass\nimport math\n\n@dataclass(frozen=True)\nclass Point:\n    x: float\n    y: float\n\n    def distance_to(self, other):\n        return math.hypot(self.x - other.x, self.y - other.y)`,
        `import dataclasses as _dataclasses\nimport math as _math\nassert _dataclasses.is_dataclass(Point)\nassert Point(1, 2) == Point(1, 2)\nassert Point(1, 2) != Point(2, 1)\nassert Point(0, 0).distance_to(Point(3, 4)) == 5\nassert Point(-1, -1).distance_to(Point(-1, -1)) == 0\nassert _math.isclose(Point(0.5, 0).distance_to(Point(0, 0)), 0.5)\nassert len({Point(1, 2), Point(1, 2)}) == 1\ntry:\n    Point(1, 2).x = 9\nexcept _dataclasses.FrozenInstanceError:\n    pass\nelse:\n    raise AssertionError("Point must be frozen.")`),
      lesson('iterable-countdown', 'Make an object iterable',
        'An iterable supplies an iterator when Python calls iter on it. Implement __iter__ to let an object participate in for loops or list conversion. A generator method containing yield creates a new iterator on each call. This separates the reusable object from each traversal’s position: two loops should not accidentally consume one shared countdown.',
        `class EvenNumbers:\n    def __init__(self, stop):\n        self.stop = stop\n\n    def __iter__(self):\n        for value in range(0, self.stop, 2):\n            yield value\n\nprint(list(EvenNumbers(7)))`,
        'Define Countdown(start), accepting a nonnegative integer. Iterating it yields start, start - 1, and so on through 0. Each traversal must be independent and reusable, and iteration must not change the public start attribute. Countdown(0) yields [0].',
        `class Countdown:\n    def __init__(self, start):\n        self.start = start\n\n    def __iter__(self):\n        # Yield values down to zero using local state.\n        pass\n`,
        ['Use local loop state rather than decrementing self.start on the object.', 'A generator loop over range(self.start, -1, -1) can yield each value, including zero.'],
        `class Countdown:\n    def __init__(self, start):\n        self.start = start\n\n    def __iter__(self):\n        for value in range(self.start, -1, -1):\n            yield value`,
        `assert list(Countdown(0)) == [0]\n_countdown = Countdown(3)\nassert list(_countdown) == [3, 2, 1, 0]\nassert list(_countdown) == [3, 2, 1, 0]\nassert _countdown.start == 3\n_left, _right = iter(_countdown), iter(_countdown)\nassert next(_left) == 3 and next(_left) == 2\nassert next(_right) == 3\nassert list(_left) == [1, 0]\nassert list(_right) == [2, 1, 0]`),
    ],
  },
  {
    id: 'algorithm-toolbox', title: 'Algorithms: search, order, and explore', level: 'Advanced',
    description: 'Reason about correctness and edge cases while building searches, a sorting algorithm, a stack parser, graph traversal, and dynamic programming.',
    lessons: [
      lesson('linear-search', 'Find the first matching position',
        'A linear search checks items in order until it finds a match. enumerate supplies each item together with its index, avoiding manual index bookkeeping. Returning immediately on a match guarantees the first occurrence. Keep the not-found result distinct from index zero: zero is a valid answer even though it is falsey. Linear search also works when the data is unsorted.',
        `def first_long_word(words, length):\n    for index, word in enumerate(words):\n        if len(word) >= length:\n            return index\n    return -1\n\nprint(first_long_word(["a", "map", "harbor"], 4))`,
        'Define find_first(values, target). Return the zero-based index of the first value equal to target, or -1 when no match exists. Work with unsorted lists, duplicates, and an empty list. Do not change the input collection.',
        `def find_first(values, target):\n    # Stop on the first match; return -1 only after all items fail.\n    pass\n`,
        ['Use enumerate(values) to get both the index and item in one loop.', 'Return index inside the equality branch and place return -1 after the loop.'],
        `def find_first(values, target):\n    for index, value in enumerate(values):\n        if value == target:\n            return index\n    return -1`,
        `assert find_first([], 4) == -1\nassert find_first([4], 4) == 0\nassert find_first([4], 5) == -1\n_values = [9, 2, 9, 1]\nassert find_first(_values, 9) == 0\nassert find_first(_values, 1) == 3\nassert _values == [9, 2, 9, 1]\nassert find_first([None, "x", None], None) == 0`),
      lesson('binary-search', 'Shrink a sorted search interval',
        'Binary search uses sorted order to discard half the remaining candidates after each comparison. Track an interval carefully: here low is included and high is excluded. To find the first duplicate, continue searching toward the left even after seeing equality. An interval that becomes empty gives an insertion position, which you must check before claiming a match. This avoids out-of-range access for empty lists.',
        `def insertion_position(values, target):\n    low, high = 0, len(values)\n    while low < high:\n        middle = (low + high) // 2\n        if values[middle] < target:\n            low = middle + 1\n        else:\n            high = middle\n    return low\n\nprint(insertion_position([2, 4, 4, 8], 4))`,
        'Define binary_find(values, target) for an ascending sorted list of numbers. Return the index of the first occurrence, or -1 if absent. Implement binary search rather than a linear scan. Do not mutate values; correctly handle empty lists and duplicate runs.',
        `def binary_find(values, target):\n    low, high = 0, len(values)\n    # Find the leftmost candidate, then verify it equals target.\n    pass\n`,
        ['When values[middle] is at least target, move high to middle so equal values remain candidates on the left.', 'Use the lower-bound loop from the example; after it, return low only if low < len(values) and values[low] == target.'],
        `def binary_find(values, target):\n    low, high = 0, len(values)\n    while low < high:\n        middle = (low + high) // 2\n        if values[middle] < target:\n            low = middle + 1\n        else:\n            high = middle\n    if low < len(values) and values[low] == target:\n        return low\n    return -1`,
        `assert binary_find([], 1) == -1\nassert binary_find([4], 4) == 0\nassert binary_find([4], 3) == -1\n_values = [-5, 0, 2, 2, 2, 9]\nfor _target, _expected in [(-5, 0), (0, 1), (2, 2), (9, 5), (-6, -1), (1, -1), (10, -1)]:\n    assert binary_find(_values, _target) == _expected\nassert _values == [-5, 0, 2, 2, 2, 9]\nassert binary_find([7] * 100, 7) == 0\nclass _ProbeList(list):\n    reads = 0\n    def __getitem__(self, index):\n        self.reads += 1\n        return super().__getitem__(index)\n    def __iter__(self):\n        for index in range(len(self)):\n            yield self[index]\n    def index(self, value, *bounds):\n        raise AssertionError("Use binary search, not list.index.")\n_probe = _ProbeList(range(4096))\nassert binary_find(_probe, 4095) == 4095\nassert _probe.reads <= 20, "Shrink the search interval instead of scanning it."`),
      lesson('insertion-sort', 'Maintain a sorted prefix',
        'Insertion sort grows a sorted prefix one item at a time. Save the current value, shift larger earlier values one position right, then place the saved value in the gap. The prefix invariant explains why the final list is sorted. Work on a copy if your contract promises not to modify the caller’s list. This quadratic algorithm is useful for learning invariants, not for replacing Python’s production sort.',
        `values = [5, 2, 4]\nfor index in range(1, len(values)):\n    current = values[index]\n    position = index - 1\n    while position >= 0 and values[position] > current:\n        values[position + 1] = values[position]\n        position -= 1\n    values[position + 1] = current\nprint(values)`,
        'Define insertion_sort(values). Return a new ascending list of the input numbers using insertion sort, not sorted() or list.sort(). Preserve duplicates and the original list. Handle empty, already sorted, reverse-sorted, negative, and fractional inputs.',
        `def insertion_sort(values):\n    result = list(values)\n    # Insert each item into the already sorted prefix.\n    return result\n`,
        ['Save result[index] before shifting, or its value will be overwritten.', 'Shift while position >= 0 and result[position] > current, then write current at position + 1.'],
        `def insertion_sort(values):\n    result = list(values)\n    for index in range(1, len(result)):\n        current = result[index]\n        position = index - 1\n        while position >= 0 and result[position] > current:\n            result[position + 1] = result[position]\n            position -= 1\n        result[position + 1] = current\n    return result`,
        `assert not {"sorted", "sort"}.intersection(insertion_sort.__code__.co_names), "Use insertion sort, not sorted() or list.sort()."\nassert insertion_sort([]) == []\nassert insertion_sort([1]) == [1]\nassert insertion_sort([1, 2, 3]) == [1, 2, 3]\nassert insertion_sort([5, 4, 3, 2, 1]) == [1, 2, 3, 4, 5]\n_values = [2, -1, 2, 0.5, -1]\nassert insertion_sort(_values) == [-1, -1, 0.5, 2, 2]\nassert _values == [2, -1, 2, 0.5, -1]\nassert insertion_sort(_values) is not _values`),
      lesson('balanced-brackets', 'Match nested pairs with a stack',
        'A stack is last-in, first-out: append pushes an item and pop removes the most recent one. That order matches nested brackets because the most recently opened bracket must close first. Merely counting opening and closing symbols misses incorrect nesting. Reject a closing bracket when the stack is empty or its type differs, and check for leftover openings at the end.',
        `stack = []\nfor character in "(())":\n    if character == "(":\n        stack.append(character)\n    elif character == ")" and stack:\n        stack.pop()\nprint(stack == [])`,
        'Define balanced(text). Return a Boolean indicating properly nested (), [], and {} pairs. Ignore all other characters (there is no special string-literal syntax). Reject mismatched, premature, or unclosed brackets. Empty text is balanced.',
        `def balanced(text):\n    pairs = {')': '(', ']': '[', '}': '{'}\n    stack = []\n    # Track openings and match every closing character.\n    pass\n`,
        ['On a closing bracket, an empty stack is already a failure. Compare with the most recent opening, not the oldest.', 'Push characters in "([{", pop and compare for characters in pairs, then return not stack after the loop.'],
        `def balanced(text):\n    pairs = {')': '(', ']': '[', '}': '{'}\n    stack = []\n    for character in text:\n        if character in "([{":\n            stack.append(character)\n        elif character in pairs:\n            if not stack or stack.pop() != pairs[character]:\n                return False\n    return not stack`,
        `for _text in ["", "plain text", "()[]{}", "{a: [b(c)]}", "(([]))"]:\n    assert balanced(_text) is True, _text\nfor _text in [")(", "([)]", "{]", "(", "[]}", "((())"]:\n    assert balanced(_text) is False, _text`),
      lesson('graph-shortest-path', 'Explore a graph in layers',
        'Breadth-first search visits a graph in increasing distance from the start. A queue processes older discoveries first. Mark nodes visited when enqueuing them, not after processing, to avoid repeated work around cycles. A parent mapping can reconstruct the route once the goal is found. This produces a shortest path by edge count in an unweighted graph, not a cheapest path with weighted edges.',
        `from collections import deque\ngraph = {"a": ["b", "c"], "b": ["d"], "c": [], "d": []}\nqueue = deque(["a"])\nseen = {"a"}\nwhile queue:\n    node = queue.popleft()\n    print(node)\n    for neighbor in graph.get(node, []):\n        if neighbor not in seen:\n            seen.add(neighbor)\n            queue.append(neighbor)`,
        'Define shortest_path(graph, start, goal) for a dictionary of node-to-neighbor lists representing a directed unweighted graph. Return a shortest node list including both endpoints, or None if unreachable. Use neighbor list order to resolve ties. Missing keys have no outgoing edges; start == goal returns [start].',
        `from collections import deque\n\ndef shortest_path(graph, start, goal):\n    # Queue nodes, remember parents, and reconstruct the route.\n    pass\n`,
        ['Use parent = {start: None} as both your visited set and reconstruction map; graph.get(node, []) handles missing keys.', 'When you dequeue goal, follow parent links back to start and reverse the path; enqueue each unseen neighbor once.'],
        `from collections import deque\n\ndef shortest_path(graph, start, goal):\n    queue = deque([start])\n    parent = {start: None}\n    while queue:\n        node = queue.popleft()\n        if node == goal:\n            path = [node]\n            while node != start:\n                node = parent[node]\n                path.append(node)\n            return path[::-1]\n        for neighbor in graph.get(node, []):\n            if neighbor not in parent:\n                parent[neighbor] = node\n                queue.append(neighbor)\n    return None`,
        `_graph = {"a": ["b", "c"], "b": ["a", "d"], "c": ["d"], "d": []}\nassert shortest_path(_graph, "a", "d") == ["a", "b", "d"]\nassert shortest_path(_graph, "d", "a") is None\nassert shortest_path({}, "x", "x") == ["x"]\nassert shortest_path({}, "x", "y") is None\nassert shortest_path({1: [2]}, 1, 2) == [1, 2]\nassert shortest_path({None: [0], 0: [1]}, None, 1) == [None, 0, 1]\nassert shortest_path({"s": ["a", "g"], "a": ["b"], "b": ["g"]}, "s", "g") == ["s", "g"]\nassert _graph == {"a": ["b", "c"], "b": ["a", "d"], "c": ["d"], "d": []}`),
      lesson('dynamic-coins', 'Reuse answers to smaller subproblems',
        'Dynamic programming saves answers to smaller problems so they are not solved repeatedly. For coin change, the best answer for an amount depends on best answers for amounts one coin smaller. Greedily choosing the largest coin can fail with arbitrary denominations. Initialize amount zero to zero coins and other amounts as unreachable, then fill answers in increasing amount order.',
        `coins = [1, 3, 4]\namount = 6\nbest = [0] + [float("inf")] * amount\nfor subtotal in range(1, amount + 1):\n    for coin in coins:\n        if coin <= subtotal:\n            best[subtotal] = min(best[subtotal], best[subtotal - coin] + 1)\nprint(best[amount])`,
        'Define min_coins(coins, amount) for positive integer denominations and a nonnegative integer amount. Coins may be reused without limit. Return the fewest coins needed, or None if impossible. Zero amount returns 0 even with no coins. Do not mutate coins; handle unsorted and repeated denominations.',
        `def min_coins(coins, amount):\n    # Build best answers for 0..amount, marking unreachable amounts.\n    pass\n`,
        ['Start best[0] at 0 and other entries at infinity. A candidate answer is best[subtotal - coin] + 1.', 'For each subtotal, try every coin no larger than it; return None only if the final value is still infinity.'],
        `def min_coins(coins, amount):\n    best = [0] + [float("inf")] * amount\n    for subtotal in range(1, amount + 1):\n        for coin in coins:\n            if coin <= subtotal:\n                best[subtotal] = min(best[subtotal], best[subtotal - coin] + 1)\n    return None if best[amount] == float("inf") else best[amount]`,
        `assert min_coins([], 0) == 0\nassert min_coins([], 3) is None\nassert min_coins([2, 4], 3) is None\nassert min_coins([1, 3, 4], 6) == 2, "Greedy 4+1+1 is not optimal."\nassert min_coins([2], 8) == 4\nassert min_coins([5, 7], 0) == 0\n_coins = [4, 1, 3, 3]\nassert min_coins(_coins, 11) == 3\nassert _coins == [4, 1, 3, 3]\nassert min_coins([7, 10], 14) == 2`),
    ],
  },
];

/** Return the lesson itself (not a course wrapper), or undefined for an unknown id. */
export function findLesson(id) {
  for (const course of courses) {
    const found = course.lessons.find(candidate => candidate.id === id);
    if (found) return found;
  }
  return undefined;
}
